 document.addEventListener('click',e=>{if(state.screen!=='pass')return;const el=e.target.closest('[data-review-back],[data-review-save],[data-review-move],[data-food-more],[data-tour-more]');if(!el)return;const s=selection();if(el.hasAttribute('data-tour-more')){sightLimit+=10;update();return;}if(el.hasAttribute('data-food-more')){foodLimit+=10;update();return;}if(el.hasAttribute('data-review-back')){s.review=false;s.step=4;changeVenue(data().route.length-1);update();return;}if(el.dataset.reviewMove){const rows=fullItinerary(),[index,direction]=el.dataset.reviewMove.split(':'),i=Number(index),j=i+(direction==='up'?-1:1);if(!rows[j]||rows[i].date!==rows[j].date)return;const positions=new Map(Array.from(document.querySelectorAll('[data-review-stop]'),node=>[node.dataset.reviewStop,node.getBoundingClientRect().top]));[rows[i],rows[j]]=[rows[j],rows[i]];s.itineraryOrder=rows.map(row=>row.id);update();if(!window.matchMedia('(prefers-reduced-motion: reduce)').matches)document.querySelectorAll('[data-review-stop]').forEach(node=>{const delta=(positions.get(node.dataset.reviewStop)??node.getBoundingClientRect().top)-node.getBoundingClientRect().top;if(delta)node.animate([{transform:`translateY(${delta}px)`},{transform:'translateY(0)'}],{duration:480,easing:'cubic-bezier(.22,1,.36,1)'});});return;}if(el.hasAttribute('data-review-save')){const route=data().route;s.completed=true;s.savedAt=new Date().toISOString();let entry;try{entry=archivePlan(route);}catch{s.completed=false;toast('저장 공간이 부족해 플랜을 저장하지 못했어요.');update();return;}resetDraft();window.BUSAN_MY_LIBRARY.showSaved(entry.id);toast('드롭 플랜을 마이에 저장했어요.');}});
